struct CachedState {
    cublasLtHandle_t handle;
    cublasLtMatmulDesc_t opDesc;
    cublasLtMatrixLayout_t Adesc, Bdesc, Cdesc;
    cublasLtMatmulAlgo_t algo;
    size_t workspaceSize;
    bool valid;
};

static std::unordered_map<CacheKey, CachedState, CacheKeyHash> g_cache;
static std::mutex g_cache_mutex;

torch::Tensor linear_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    // Guard: only take fast path for contiguous float32 CUDA 2D tensors
    if (!x.is_cuda() || x.scalar_type() != at::kFloat || x.dim() != 2 ||
        !weight.is_cuda() || weight.scalar_type() != at::kFloat || weight.dim() != 2 ||
        !bias.is_cuda() || bias.scalar_type() != at::kFloat || bias.dim() != 1 ||
        !x.is_contiguous() || !weight.is_contiguous() || !bias.is_contiguous()) {
        return torch::matmul(x, weight.t()) + bias;
