    int device = x.device().index();
    CacheKey key{device, M, K, N};

    std::unique_lock<std::mutex> lock(g_cache_mutex);
    auto it = g_cache.find(key);
    if (it == g_cache.end()) {
        CachedState st;
        st.valid = false;
        st.workspaceSize = 32 * 1024 * 1024;

        cublasLtCreate(&st.handle);

        cublasLtMatmulDescCreate(&st.opDesc, CUBLAS_COMPUTE_32F, CUDA_R_32F);
        // We compute: output = x * weight^T + bias
        // cublasLt: C = alpha * op(A) * op(B) + beta * C
        // We set A=weight (NxK), B=x (MxK), so op(A)=A^T (KxN), op(B)=B^T (KxM)... 
        // Actually use: C(MxN) = x(MxK) * weight^T(KxN)
        // Map as: A=x row-major MxK (no transpose), B=weight row-major NxK (transpose needed)
        // cublasLt column-major: A_col = x^T (KxM), B_col = weight^T (KxN)
        // C_col(NxM) = weight(NxK) * x^T(KxM) => transB=N, transA=T
        // Simplest: use transa=CUBLAS_OP_N for weight, transb=CUBLAS_OP_T for x
        cublasOperation_t transa = CUBLAS_OP_T;  // weight stored as NxK, we need KxN
        cublasOperation_t transb = CUBLAS_OP_N;
        cublasLtMatmulDescSetAttribute(st.opDesc, CUBLASLT_MATMUL_DESC_TRANSA, &transa, sizeof(transa));
        cublasLtMatmulDescSetAttribute(st.opDesc, CUBLASLT_MATMUL_DESC_TRANSB, &transb, sizeof(transb));

