        cublasLtEpilogue_t epilogue = CUBLASLT_EPILOGUE_BIAS;
        cublasLtMatmulDescSetAttribute(st.opDesc, CUBLASLT_MATMUL_DESC_EPILOGUE, &epilogue, sizeof(epilogue));
        // bias pointer set per-call since it may vary

        // Layouts: column-major convention
        // A = weight: NxK stored row-major => leading dim K, col-major shape KxN
        cublasLtMatrixLayoutCreate(&st.Adesc, CUDA_R_32F, K, N, K);
        // B = x: MxK stored row-major => leading dim K, col-major shape KxM  
        cublasLtMatrixLayoutCreate(&st.Bdesc, CUDA_R_32F, K, M, K);
        // C = output: MxN stored row-major => leading dim N, col-major shape NxM
        cublasLtMatrixLayoutCreate(&st.Cdesc, CUDA_R_32F, N, M, N);

        cublasLtMatmulPreference_t pref;
        cublasLtMatmulPreferenceCreate(&pref);
        cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
