// ---- shape-specialized linear via cuBLAS sgemm with cached handle ----
// Computes: output = x @ weight^T + bias
// x: [M, K], weight: [N, K], bias: [N], output: [M, N]

struct LinearCacheKey {
    int M, N, K;
    int device_id;
    bool operator==(const LinearCacheKey& o) const {
        return M==o.M && N==o.N && K==o.K && device_id==o.device_id;
    }
};

struct LinearCacheKeyHash {
    size_t operator()(const LinearCacheKey& k) const {
        size_t h = (size_t)k.M;
        h = h * 131071 ^ (size_t)k.N;
        h = h * 131071 ^ (size_t)k.K;
        h = h * 131071 ^ (size_t)k.device_id;
        return h;
    }
};

torch::Tensor linear_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    // Validate inputs
    if (!x.is_cuda() || !weight.is_cuda() || !bias.is_cuda()) {
        // fallback
        return torch::addmm(bias, x, weight.t());
    }
    if (x.scalar_type() != at::kFloat || weight.scalar_type() != at::kFloat || bias.scalar_type() != at::kFloat) {
        return torch::addmm(bias, x, weight.t());
    }
    if (x.dim() != 2 || weight.dim() != 2 || bias.dim() != 1) {
        return torch::addmm(bias, x, weight.t());
    }
    if (!x.is_contiguous() || !weight.is_contiguous()) {
        auto xc = x.contiguous();
        auto wc = weight.contiguous();
        return torch::addmm(bias, xc, wc.t());
    }

    int M = (int)x.size(0);
    int K = (int)x.size(1);
    int N = (int)weight.size(0);

    if (weight.size(1) != K || bias.size(0) != N) {
        return torch::addmm(bias, x, weight.t());
    }

    // Allocate output and initialize with bias via expand+copy (row broadcast)
    // Then sgemm accumulates into it.
    // output[M,N] = bias broadcast + x @ weight^T
    // Use cuBLAS: C = alpha * A * B + beta * C
    // We want: output = x [M,K] * weight^T [K,N]  (row-major)
    // cuBLAS is column-major. For row-major A[M,K] * B[N,K]^T = C[M,N]:
    //   Interpret as col-major: B^T [K,N] treated as col-major B[N,K], then
    //   C^T[N,M] = weight[N,K] * x^T[K,M], so:
    //   sgemm(N, N, M, N, K, alpha, weight_ptr, N, x_ptr, K, beta, out_ptr, N)
    //   where A=weight[N,K] (lda=K -> but cuBLAS col-major lda=N for N rows)
    // Simpler: use the standard trick:
    //   C(M,N) row-major = A(M,K) row-major * B^T(K,N) row-major
    //   In cuBLAS col-major: C^T(N,M) = B(N,K) * A^T(K,M)
    //   => sgemm(CUBLAS_OP_T, CUBLAS_OP_N, N, M, K, &alpha, weight, K, x, K, &beta, out, N)
    //   i.e. op(A)=weight^T [K,N->N,K col], op(B)=x [K,M col], C=[N,M col]
    //   Actually standard row-major GEMM trick:
    //   C = A*B  =>  C^T = B^T * A^T
    //   Here C[M,N]=x[M,K]*W^T[K,N]
    //   C^T[N,M] = W[N,K] * x^T[K,M]
    //   cuBLAS col-major: sgemm(OP_N, OP_N, N, M, K, alpha, W, N, x^T, K, beta, C^T, N)
    //   but x^T is not contiguous. Use instead:
    //   C^T[N,M] = W[N,K] * x^T[K,M] with OP_T on x:
    //   sgemm(OP_N, OP_T, N, M, K, alpha, W_ptr(lda=K? no), ...)
    // Cleanest approach for row-major inputs:
    //   sgemm(OP_T, OP_N, N, M, K, 1, weight(lda=K), x(lda=K), 0, out(lda=N))
    //   This computes col-major: C[N,M] = weight^T[N,K] * x[K,M]
    //   In row-major: out[M,N] = x[M,K] * weight^T[K,N] â

    auto out = bias.unsqueeze(0).expand({M, N}).contiguous();

    float alpha = 1.0f;
    float beta  = 1.0f;  // add into bias-initialized out

    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();
    auto stream = at::cuda::getCurrentCUDAStream();
    cublasSetStream(handle, stream);

    // sgemm: op(A)=weight^T, op(B)=x, C=out
    // m=N, n=M, k=K
    // lda=K (weight stored row-major [N,K], col-major lda for OP_T = K)
    // ldb=K (x stored row-major [M,K], col-major lda for OP_N = K)
    // ldc=N (out stored row-major [M,N], col-major lda = N)
    cublasStatus_t status = cublasSgemm(
        handle,
        CUBLAS_OP_T,  // op(A): transpose weight
        CUBLAS_OP_N,  // op(B): no-transpose x
        N, M, K,
        &alpha,
        weight.data_ptr<float>(), K,
        x.data_ptr<float>(),      K,
        &beta,
        out.data_ptr<float>(),    N
    );

    if (status != CUBLAS_STATUS_SUCCESS) {
        // fallback on error
        return torch::addmm(bias, x, weight.t());
    }

