CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublasLt.h>
#include <ATen/cuda/CUDAContext.h>
#include <mutex>
#include <unordered_map>
#include <tuple>

// ---- cached cublasLt linear ----

struct CacheKey {
    int device;
    int64_t M, K, N;
    bool operator==(const CacheKey& o) const {
        return device == o.device && M == o.M && K == o.K && N == o.N;
    }
};

struct CacheKeyHash {
    size_t operator()(const CacheKey& k) const {
        size_t h = std::hash<int>()(k.device);
        h ^= std::hash<int64_t>()(k.M) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<int64_t>()(k.K) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<int64_t>()(k.N) + 0x9e3779b9 + (h << 6) + (h >> 2);
        return h;
    }
};

struct CachedState {
    cublasLtHandle_t handle;
    cublasLtMatmulDesc_t opDesc;
    cublasLtMatrixLayout_t Adesc, Bdesc, Cdesc;
    cublasLtMatmulAlgo_t algo;
    size_t workspaceSize;
    bool valid;
};

static std::unordered_map<CacheKey, CachedState, CacheKeyHash> g_cache;
static std::mutex g_cache_mutex;

torch::Tensor linear_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    // Guard: only take fast path for contiguous float32 CUDA 2D tensors
    if (!x.is_cuda() || x.scalar_type() != at::kFloat || x.dim() != 2 ||
        !weight.is_cuda() || weight.scalar_type() != at::kFloat || weight.dim() != 2 ||
        !bias.is_cuda() || bias.scalar_type() != at::kFloat || bias.dim() != 1 ||
        !x.is_contiguous() || !weight.is_contiguous() || !bias.is_contiguous()) {
        return torch::matmul(x, weight.t()) + bias;
    }

    int64_t M = x.size(0);
    int64_t K = x.size(1);
    int64_t N = weight.size(0);
    if (weight.size(1) != K || bias.size(0) != N) {
        return torch::matmul(x, weight.t()) + bias;
    }

    int device = x.device().index();
    CacheKey key{device, M, K, N};

    std::unique_lock<std::mutex> lock(g_cache_mutex);
    auto it = g_cache.find(key);
    if (it == g_cache.end()) {
        CachedState st;
        st.valid = false;
        st.workspaceSize = 32 * 1024 * 1024;

        cublasLtCreate(&st.handle);

        cublasLtMatmulDescCreate(&st.opDesc, CUBLAS_COMPUTE_32F, CUDA_R_32F);
        // We compute: output = x * weight^T + bias
        // cublasLt: C = alpha * op(A) * op(B) + beta * C
        // We set A=weight (NxK), B=x (MxK), so op(A)=A^T (KxN), op(B)=B^T (KxM)... 
        // Actually use: C(MxN) = x(MxK) * weight^T(KxN)
        // Map as: A=x row-major MxK (no transpose), B=weight row-major NxK (transpose needed)
        // cublasLt column-major: A_col = x^T (KxM), B_col = weight^T (KxN)
        // C_col(NxM) = weight(NxK) * x^T(KxM) => transB=N, transA=T
        // Simplest: use transa=CUBLAS_OP_N for weight, transb=CUBLAS_OP_T for x
        cublasOperation_t transa = CUBLAS_OP_T;  // weight stored as NxK, we need KxN
        cublasOperation_t transb = CUBLAS_OP_N;
        cublasLtMatmulDescSetAttribute(st.opDesc, CUBLASLT_MATMUL_DESC_TRANSA, &transa, sizeof(transa));
        cublasLtMatmulDescSetAttribute(st.opDesc, CUBLASLT_MATMUL_DESC_TRANSB, &transb, sizeof(transb));

        // Epilogue: bias only (no ReLU here, ReLU/divide handled separately)
        cublasLtEpilogue_t epilogue = CUBLASLT_EPILOGUE_BIAS;
        cublasLtMatmulDescSetAttribute(st.opDesc, CUBLASLT_MATMUL_DESC_EPILOGUE, &epilogue, sizeof(epilogue));
        // bias pointer set per-call since it may vary

        // Layouts: column-major convention
        // A = weight: NxK stored row-major => leading dim K, col-major shape KxN
        cublasLtMatrixLayoutCreate(&st.Adesc, CUDA_R_32F, K, N, K);
        // B = x: MxK stored row-major => leading dim K, col-major shape KxM  
        cublasLtMatrixLayoutCreate(&st.Bdesc, CUDA_R_32F, K, M, K);
        // C = output: MxN stored row-major => leading dim N, col-major shape NxM
        cublasLtMatrixLayoutCreate(&st.Cdesc, CUDA_R_32F, N, M, N);

        cublasLtMatmulPreference_t pref;
        cublasLtMatmulPreferenceCreate(&pref);
        cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
                                             &st.workspaceSize, sizeof(st.workspaceSize));

        cublasLtMatmulHeuristicResult_t hres;
        int nres = 0;
        cublasStatus_t hstat = cublasLtMatmulAlgoGetHeuristic(
            st.handle, st.opDesc, st.Adesc, st.Bdesc, st.Cdesc, st.Cdesc,
            pref, 1, &hres, &nres);
        cublasLtMatmulPreferenceDestroy(pref);

        if (hstat == CUBLAS_STATUS_SUCCESS && nres > 0) {
            st.algo = hres.algo;
            st.workspaceSize = hres.workspaceSize;
            st.valid = true;
        }
        g_cache[key] = st;
        it = g_cache.find(key);
    }

    CachedState& st = it->second;
    if (!st.valid) {
        lock.unlock();
        return torch::matmul(x, weight.t()) + bias;
    }

    auto output = torch::empty({M, N}, x.options());
    // Set bias pointer (per-call attribute)
    float* bias_ptr = bias.data_ptr<float>();
    cublasLtMatmulDescSetAttribute(st.opDesc, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &bias_ptr, sizeof(bias_ptr));

    float alpha = 1.0f, beta = 0.0f;
    torch::Tensor ws;
    void* ws_ptr = nullptr;
    if (st.workspaceSize > 0) {
        ws = torch::empty({(int64_t)st.workspaceSize}, torch::dtype(torch::kUInt8).device(x.device()));
        ws_ptr = ws.data_ptr();
    }

    cublasStatus_t stat = cublasLtMatmul(
        st.handle, st.opDesc,
        &alpha,
        weight.data_ptr<float>(), st.Adesc,
        x.data_ptr<float>(),      st.Bdesc,
        &beta,
        output.data_ptr<float>(), st.Cdesc,
        output.data_ptr<float>(), st.Cdesc,
        &st.algo,
        ws_ptr, st.workspaceSize,
        at::cuda::getCurrentCUDAStream());

    lock.unlock();

    if (stat != CUBLAS_STATUS_SUCCESS) {
        return torch::matmul(x, weight.t()) + bias;
    }
    return output;
}

// ---- fused ReLU + divide (unchanged from champion) ----

__global__ void relu_divide_vec4_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    float inv_divisor,
    int64_t n_vec4)
{
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n_vec4) {
        float4 v = ((const float4*)input)[idx];
        v.x = fmaxf(v.x, 0.0f) * inv_divisor;
        v.y = fmaxf(v.y, 0.0f) * inv_divisor;
        v.z = fmaxf(v.z, 0.0f) * inv_divisor;
        v.w = fmaxf(v.w, 0.0f) * inv_divisor;
        ((float4*)output)[idx] = v;
    }
}

__global__ void relu_divide_scalar_tail_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    float inv_divisor,
    int64_t offset,
    int64_t total)
{
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x + offset;
    if (idx < total) {
        output[idx] = fmaxf(input[idx], 0.0f) * inv_divisor;
    }
}

torch::Tensor relu_divide_cuda(torch::Tensor x, double divisor) {
    TORCH_CHECK(x.is_cuda(), "relu_divide_cuda: input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "relu_divide_cuda: input must be float32");
    torch::Tensor x_c = x.is_contiguous() ? x : x.contiguous();
    auto out = torch::empty_like(x_c);
    int64_t numel = x_c.numel();
    float inv_divisor = 1.0f / (float)divisor;
    const int BLOCK = 256;
    auto stream = at::cuda::getCurrentCUDAStream();
    int64_t n_vec4 = numel / 4;
    int64_t remainder = numel % 4;
    if (n_vec4 > 0) {
        int64_t grid = (n_vec4 + BLOCK - 1) / BLOCK;
        relu_divide_vec4_kernel<<<grid, BLOCK, 0, stream>>>(
            x_c.data_ptr<float>(), out.data_ptr<float>(), inv_divisor, n_vec4);
    }
    if (remainder > 0) {
        relu_divide_scalar_tail_kernel<<<1, BLOCK, 0, stream>>>(
            x_c.data_ptr<float>(), out.data_ptr<float>(), inv_divisor,
            n_vec4 * 4, numel);
    }
    return out;
}
